<?php $title='Clientes GDA'; ?>
<section class="page-head"><div><h1>Clientes GDA</h1><p>Administre clientes e seus acessos.</p></div><a class="btn primary" href="<?= e(base_url('clientes/novo')) ?>">+ Novo cliente</a></section>
<form class="filters" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Nome, identificador, e-mail ou telefone"><select name="status"><option value="">Todos os status</option><option value="active" <?= $status==='active'?'selected':'' ?>>Ativos</option><option value="inactive" <?= $status==='inactive'?'selected':'' ?>>Inativos</option></select><button class="btn" type="submit">Filtrar</button></form>
<section class="panel"><?php if(!$clients): ?><div class="empty"><b>Nenhum cliente encontrado</b><p>Cadastre o primeiro cliente ou ajuste os filtros.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Administradora</th><th>Contato</th><th>Projetos</th><th>Status</th><th>Cadastro</th><th>Ações</th></tr></thead><tbody><?php foreach($clients as $c): ?><tr><td><b><?= e($c['name']) ?></b><small><?= e($c['identifier']) ?></small></td><td><?= e($c['administrator_name']) ?></td><td><?= e($c['email']) ?><small><?= e($c['phone']) ?></small></td><td><?= (int)$c['project_count'] ?></td><td><span class="badge <?= e($c['status']) ?>"><?= $c['status']==='active'?'Ativo':'Inativo' ?></span></td><td><?= e(date('d/m/Y',strtotime($c['created_at']))) ?></td><td class="actions"><a href="<?= e(base_url('clientes/'.$c['id'])) ?>">Ver</a><a href="<?= e(base_url('clientes/'.$c['id'].'/editar')) ?>">Editar</a><form method="post" action="<?= e(base_url('clientes/'.$c['id'].'/status')) ?>" data-confirm="Confirma a alteração de status?"><?= csrf_field() ?><button type="submit"><?= $c['status']==='active'?'Inativar':'Ativar' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><nav class="pagination"><?php for($i=1;$i<=$pages;$i++): ?><a class="<?= $i===$page?'active':'' ?>" href="?<?= e(http_build_query(['q'=>$q,'status'=>$status,'page'=>$i])) ?>"><?= $i ?></a><?php endfor; ?></nav><?php endif; ?></section>

